    if (a.length !== b.length) return false;
    const s = new Set(a);
    return b.every((v) => s.has(v));
  }

  form.addEventListener('submit', (event) => {
    event.preventDefault();

    let correct = 0;
    Object.keys(answers).forEach((q) => {
      if (arraysEqualAsSets(getSelected(q), answers[q])) correct++;
