          <p id="q1-help" class="help-text">Tip: Static typing means variable types are checked at compile time. Select all that apply.</p>
          <div class="options">
            <div class="option">
              <input id="q1-a" type="checkbox" name="q1" value="java">
              <label for="q1-a">Java</label>
            </div>
            <div class="option">
              <input id="q1-b" type="checkbox" name="q1" value="python">
              <label for="q1-b">Python</label>
            </div>
            <div class="option">
              <input id="q1-c" type="checkbox" name="q1" value="rust">
              <label for="q1-c">Rust</label>
            </div>
            <div class="option">
              <input id="q1-d" type="checkbox" name="q1" value="javascript">
              <label for="q1-d">JavaScript</label>
            </div>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>2. Which languages commonly run on the JVM?</legend>
          <div class="options">
            <div class="option">
              <input id="q2-a" type="checkbox" name="q2" value="kotlin">
              <label for="q2-a">Kotlin</label>
            </div>
            <div class="option">
              <input id="q2-b" type="checkbox" name="q2" value="scala">
              <label for="q2-b">Scala</label>
            </div>
            <div class="option">
              <input id="q2-c" type="checkbox" name="q2" value="go">
              <label for="q2-c">Go</label>
            </div>
            <div class="option">
              <input id="q2-d" type="checkbox" name="q2" value="clojure">
              <label for="q2-d">Clojure</label>
            </div>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>3. Which of these are functional programming languages?</legend>
          <div class="options">
            <div class="option">
              <input id="q3-a" type="checkbox" name="q3" value="haskell">
              <label for="q3-a">Haskell</label>
            </div>
            <div class="option">
              <input id="q3-b" type="checkbox" name="q3" value="elixir">
              <label for="q3-b">Elixir</label>
            </div>
            <div class="option">
              <input id="q3-c" type="checkbox" name="q3" value="cpp">
              <label for="q3-c">C++</label>
            </div>
            <div class="option">
              <input id="q3-d" type="checkbox" name="q3" value="cobol">
              <label for="q3-d">COBOL</label>
            </div>
          </div>
        </fieldset>
      </div>

      <button type="submit">Submit answers</button>

      <p id="quiz-result" class="result" role="status" aria-live="polite"></p>
    </form>
