    (function () {
      const form = document.getElementById('quiz-form');
      const result = document.getElementById('quiz-result');

      const answers = {
        q1: ['java', 'rust'],
        q2: ['kotlin', 'scala', 'clojure'],
        q3: ['haskell', 'elixir'],
      };

      function getSelected(name) {
        return Array.from(
          form.querySelectorAll('input[name="' + name + '"]:checked')
        ).map(function (el) { return el.value; });
      }

      function arraysEqualAsSets(a, b) {
        if (a.length !== b.length) return false;
        const s = new Set(a);
        return b.every(function (v) { return s.has(v); });
      }

      form.addEventListener('submit', function (event) {
        event.preventDefault();

        let correct = 0;
        Object.keys(answers).forEach(function (q) {
          if (arraysEqualAsSets(getSelected(q), answers[q])) correct++;
        });

        const total = Object.keys(answers).length;
        result.classList.remove('is-success', 'is-partial');
        result.classList.add(correct === total ? 'is-success' : 'is-partial');
        result.textContent = 'You got ' + correct + ' out of ' + total + ' question' + (total === 1 ? '' : 's') + ' fully correct.';
      });
    })();
  </script>
